arguments.command:
cat > /tmp/match.py <<'PY'
import pandas as pd,numpy as np, pickle, warnings
from pymatgen.core import Structure
from pymatgen.analysis.structure_matcher import StructureMatcher
warnings.filterwarnings('ignore')
tr=pd.read_csv('nlo_shg_train.csv');po=pd.read_csv('nlo_pool.csv'); ss=[Structure.from_str(x,fmt='poscar') for x in pd.concat([tr,po]).poscar]
for tol in [(0.3,0.5,10),(0.5,1,15)]:
 sm=StructureMatcher(ltol=tol[0],stol=tol[1],angle_tol=tol[2],primitive_cell=True,scale=True,attempt_supercell=True)
 print('TOL',tol)
 for j in range(100):
  vals=[]
  for i in range(200):
   try:r=sm.get_rms_anonymous(ss[i],ss[200+j])
   except:r=None
   if r is not None: vals.append((r[0],i,tr.iloc[i].formula,tr.iloc[i].shg))
  vals.sort()
  if vals:print(po.iloc[j].candidate_id,po.iloc[j].formula,vals[:4])
PY
python /tmp/match.py > /tmp/matchout

